    };
    assert!(Config::parse(&with("targets = [\"a:1\"]")).is_err());
    assert!(Config::parse(&with("command = [\"x\"]")).is_err());
    assert!(Config::parse(&PROCESS_WATCH.replace("learn_for = \"7d\"", "")).is_err());
